content.query:
let privUsers = IdentityInfo
| where TimeGenerated > ago(30d)
| summarize arg_max(TimeGenerated, AssignedRoles) by AccountUPN
| where array_length(AssignedRoles) > 0
| distinct AccountUPN = tolower(AccountUPN);
let signins = SigninLogs
| where TimeGenerated > ago({TimeRange})
| where ResultType == '0'
| extend UserLower = tolower(UserPrincipalName)
| extend AuthDetailsStr = tostring(AuthenticationDetails)
| extend IsPhishingResistant = AuthDetailsStr has_any ('FIDO2', 'Windows Hello for Business', 'Certificate-based authentication', 'Passkey')
| extend IsMfa = (AuthenticationRequirement == 'multiFactorAuthentication' or IsPhishingResistant)
| extend IsLegacy = ClientAppUsed in~ ('IMAP4', 'POP3', 'SMTP', 'Exchange ActiveSync', 'Exchange Web Services', 'Autodiscover', 'MAPI Over HTTP', 'Other clients')
| extend IsPrivileged = UserLower in (privUsers);
let kpiMfa = signins | summarize Metric = 'MFA Coverage % (ML1)', Value = round(100.0 * countif(IsMfa) / max_of(count(), 1), 1);
let kpiPrAll = signins | summarize Metric = 'Phishing-Resistant % All Users (ML2/ML3)', Value = round(100.0 * countif(IsPhishingResistant) / max_of(count(), 1), 1);
let kpiPrPriv = signins | where IsPrivileged | summarize Metric = 'Phishing-Resistant % Privileged (ML2)', Value = round(100.0 * countif(IsPhishingResistant) / max_of(count(), 1), 1);
let kpiLegacy = signins | where IsLegacy | summarize Metric = 'Successful Legacy Auth Sign-ins (ML1)', Value = toreal(count());
let kpiCaExcl = AuditLogs | where TimeGenerated > ago({TimeRange}) | where OperationName has 'conditional access' and tostring(TargetResources) has_any ('excludeUsers', 'excludeGroups', 'excludeRoles') | summarize Metric = 'CA Exclusion Changes (ML2/ML3)', Value = toreal(count());
union kpiMfa, kpiPrAll, kpiPrPriv, kpiLegacy, kpiCaExcl
